const searchDecisions = `-- name: SearchDecisions :many
SELECT d.id, d.workspace_id, d.topic, d.question, d.answer, d.scope, d.source, d.run_id, d.item_id, d.created_at, d.forgotten_at, ts_rank(to_tsvector('simple'::regconfig, d.topic || ' ' || d.question || ' ' || d.answer),
  replace(plainto_tsquery('simple'::regconfig, $1::text)::text, '&', '|')::tsquery)::float8 AS rank
FROM public.decision_memory d
WHERE d.workspace_id = $2 AND d.forgotten_at IS NULL
  AND to_tsvector('simple'::regconfig, d.topic || ' ' || d.question || ' ' || d.answer)
      @@ replace(plainto_tsquery('simple'::regconfig, $1::text)::text, '&', '|')::tsquery
  AND ($3::text = '' OR d.scope->>'behavior' = $3::text)
ORDER BY rank DESC, d.created_at DESC, d.id DESC
LIMIT $4::int
`

type SearchDecisionsParams struct {
	Query       string
	WorkspaceID pgtype.UUID
	Behavior    string
	MaxRows     int32
}

type SearchDecisionsRow struct {
	ID          int64
	WorkspaceID pgtype.UUID
	Topic       string
	Question    string
	Answer      string
	Scope       []byte
	Source      string
	RunID       pgtype.Int8
	ItemID      pgtype.Int8
	CreatedAt   pgtype.Timestamptz
	ForgottenAt pgtype.Timestamptz
	Rank        float64
}

// Any query word matches (the words are OR-ed); best rank first. An empty
// behavior filter matches every scope.
func (q *Queries) SearchDecisions(ctx context.Context, arg SearchDecisionsParams) ([]SearchDecisionsRow, error) {
	rows, err := q.db.Query(ctx, searchDecisions,
		arg.Query,
		arg.WorkspaceID,
		arg.Behavior,
		arg.MaxRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchDecisionsRow
	for rows.Next() {
		var i SearchDecisionsRow
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Topic,
			&i.Question,
			&i.Answer,
			&i.Scope,
			&i.Source,
			&i.RunID,
			&i.ItemID,
			&i.CreatedAt,
			&i.ForgottenAt,
			&i.Rank,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const searchReusableDecisions = `-- name: SearchReusableDecisions :many
SELECT d.id, d.workspace_id, d.topic, d.question, d.answer, d.scope, d.source, d.run_id, d.item_id, d.created_at, d.forgotten_at, ts_rank(to_tsvector('simple'::regconfig, d.topic || ' ' || d.question || ' ' || d.answer),
  replace(plainto_tsquery('simple'::regconfig, $1::text)::text, '&', '|')::tsquery)::float8 AS rank
FROM public.decision_memory d
WHERE d.workspace_id = $2 AND d.forgotten_at IS NULL AND d.source <> 'auto_undone'
  AND to_tsvector('simple'::regconfig, d.topic || ' ' || d.question || ' ' || d.answer)
      @@ replace(plainto_tsquery('simple'::regconfig, $1::text)::text, '&', '|')::tsquery
  AND NOT EXISTS (
    SELECT 1 FROM public.decision_memory u
    WHERE u.workspace_id = d.workspace_id AND u.source = 'auto_undone' AND d.item_id IS NOT NULL AND u.item_id = d.item_id)
ORDER BY rank DESC, d.created_at DESC, d.id DESC
LIMIT $3::int
`

type SearchReusableDecisionsParams struct {
	Query       string
	WorkspaceID pgtype.UUID
	MaxRows     int32
}

type SearchReusableDecisionsRow struct {
	ID          int64
	WorkspaceID pgtype.UUID
	Topic       string
	Question    string
	Answer      string
	Scope       []byte
	Source      string
	RunID       pgtype.Int8
	ItemID      pgtype.Int8
	CreatedAt   pgtype.Timestamptz
	ForgottenAt pgtype.Timestamptz
	Rank        float64
}

// SearchDecisions for reuse as evidence: undone decisions are left out,
// and so is any decision about an item whose auto write the owner undid.
func (q *Queries) SearchReusableDecisions(ctx context.Context, arg SearchReusableDecisionsParams) ([]SearchReusableDecisionsRow, error) {
	rows, err := q.db.Query(ctx, searchReusableDecisions, arg.Query, arg.WorkspaceID, arg.MaxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchReusableDecisionsRow
	for rows.Next() {
		var i SearchReusableDecisionsRow
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Topic,
			&i.Question,
			&i.Answer,
			&i.Scope,
			&i.Source,
			&i.RunID,
			&i.ItemID,
			&i.CreatedAt,
			&i.ForgottenAt,
			&i.Rank,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const selectBehaviorRunClaimCandidate = `-- name: SelectBehaviorRunClaimCandidate :one
SELECT r.id, r.workspace_id FROM public.behavior_runs r
WHERE ((r.status = 'pending' AND r.run_at <= $1::timestamptz)
    OR (r.status = 'running' AND r.locked_until <= $1::timestamptz))
  AND r.attempts < $2::int
  AND NOT EXISTS (SELECT 1 FROM public.workflow_runtime_modes m
                  WHERE m.workspace_id = r.workspace_id AND m.mode = 'workflow')
  AND NOT EXISTS (SELECT 1 FROM public.workflow_executions e
                  WHERE e.workspace_id = r.workspace_id AND e.legacy_run_id = r.id)
ORDER BY (r.status = 'running') DESC, r.run_at, r.id
FOR UPDATE OF r SKIP LOCKED LIMIT 1
`

type SelectBehaviorRunClaimCandidateParams struct {
	AtTime      pgtype.Timestamptz
	MaxAttempts int32
}

type SelectBehaviorRunClaimCandidateRow struct {
	ID          int64
	WorkspaceID pgtype.UUID
}

// A due pending run, or a running run whose lease ended. Runs of a
// cut-over workspace and runs owned by a workflow execution are never
// candidates; the claim re-checks the workspace's runtime mode under its
// KEY SHARE lock (this filter only skips them cheaply).
func (q *Queries) SelectBehaviorRunClaimCandidate(ctx context.Context, arg SelectBehaviorRunClaimCandidateParams) (SelectBehaviorRunClaimCandidateRow, error) {
	row := q.db.QueryRow(ctx, selectBehaviorRunClaimCandidate, arg.AtTime, arg.MaxAttempts)
	var i SelectBehaviorRunClaimCandidateRow
	err := row.Scan(&i.ID, &i.WorkspaceID)
	return i, err
}

